fn numeric_values_only_widen() {
    use BaseType::{Byte, Decimal, Double, Float, Integer, Long, Short, String};
    for (from, to) in [
        (Byte, Short),
        (Short, Integer),
        (Integer, Long),
        (Byte, Long),
        (Float, Double),
        (Long, Long),
    ] {
        assert!(widens_to(from, to), "{from:?} -> {to:?}");
    }
    for (from, to) in [
        (Long, Integer),
